inlineStyles:
.hero{padding:64px 0 18px}
.hero h1{white-space:nowrap}
@media(max-width:560px){.hero h1{white-space:normal}}
.stepper{display:flex;align-items:center;justify-content:center;gap:10px;margin:0 auto 34px;flex-wrap:wrap}
.st{display:inline-flex;align-items:center;gap:9px;font-size:13.5px;font-weight:600;color:var(--text-3)}
.st i{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:12px;border:1.5px solid var(--line);color:var(--text-3)}
.st.done{color:var(--text-2)}.st.done i{background:rgba(37,211,102,.14);border-color:rgba(37,211,102,.55);color:#7ff0a9}
.st.now{color:var(--text)}.st.now i{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.st-line{width:34px;height:1px;background:var(--line)}
@media(max-width:520px){.st-line{width:14px}.stepper{gap:6px}.st{font-size:12.5px}}

/* prep video (faux player) */
.prep{max-width:840px;margin:40px auto 0;text-align:center}
.prep-line{font-size:clamp(15px,1.6vw,17px);color:var(--text-2);margin:0 0 24px}
.prep-v{border:1px solid rgba(212,165,74,.35);box-shadow:0 50px 100px -46px rgba(0,0,0,.95),0 0 0 8px rgba(242,236,224,.04)}
.prep-player{position:relative;aspect-ratio:16/9;border-radius:22px;overflow:hidden;border:1px solid var(--line);cursor:pointer;
  box-shadow:0 40px 90px -46px rgba(0,0,0,.95)}
.prep-player img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.prep-player::after{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(70% 70% at 50% 50%,rgba(0,0,0,.05),rgba(0,0,0,.4))}
.prep-play{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);z-index:2;width:82px;height:82px;border-radius:50%;display:grid;place-items:center;
  background:var(--accent);color:var(--accent-ink);box-shadow:0 18px 46px -12px rgba(0,0,0,.7);transition:transform .3s var(--ease)}
.prep-play svg{width:30px;height:30px;margin-left:4px}
.prep-player:hover .prep-play{transform:translate(-50%,-50%) scale(1.06)}
.prep-len{position:absolute;right:16px;bottom:14px;z-index:2;font-size:12.5px;font-weight:600;color:#fff;background:rgba(0,0,0,.55);border-radius:6px;padding:4px 8px}

/* steps, centre-aligned */
.steps{max-width:880px;margin:64px auto 0;display:flex;flex-direction:column;gap:24px}
.step{background:linear-gradient(180deg,var(--surface-2),var(--surface));border:1px solid var(--line);border-radius:12px;padding:38px 32px 40px;text-align:center;box-shadow:0 34px 64px -44px rgba(0,0,0,.9)}
.step-n{width:46px;height:46px;border-radius:50%;margin:0 auto 16px;display:grid;place-items:center;background:var(--bg);border:2px solid var(--accent);
  font:400 24px/1 var(--display);color:var(--accent)}
.step h3{font-size:clamp(26px,2.6vw,32px);margin:0 auto 14px;max-width:44ch}
.step h3+.gmail{margin-top:26px}
.step .sub{margin:0 auto 24px;color:var(--text-2);font-size:16px;max-width:50ch}
.cal-btns{display:flex;flex-wrap:wrap;gap:12px;justify-content:center}
.cal-btn{display:inline-flex;align-items:center;gap:10px;font-weight:600;font-size:15px;color:#1f1f1f;background:#fff;border:1px solid rgba(11,19,36,.14);border-radius:8px;padding:13px 20px;min-height:48px;
  transition:transform .2s var(--ease),box-shadow .2s var(--ease)}
.cal-btn:hover{transform:translateY(-2px);box-shadow:0 12px 28px -14px rgba(11,19,36,.45)}
.cal-btn svg{width:22px;height:22px;flex:none}

/* Gmail mockup */
.gmail{border-radius:16px;overflow:hidden;background:#fff;color:#202124;border:1px solid rgba(11,19,36,.1);box-shadow:0 30px 70px -36px rgba(11,19,36,.5);font-size:14px;line-height:1.3;text-align:left;width:100%;
  font-family:"Google Sans",Roboto,Arial,sans-serif}
.gm-top{display:flex;align-items:center;gap:16px;padding:9px 16px;border-bottom:1px solid #eceff1}
.gm-burger{width:20px;height:20px;color:#5f6368;flex:none}
.gm-logo{display:flex;align-items:center;gap:8px;flex:none}.gm-logo svg{width:34px;height:26px}.gm-logo span{font-size:21px;color:#5f6368}
.gm-search{flex:1;max-width:520px;display:flex;align-items:center;gap:12px;background:#eaf1fb;border-radius:24px;padding:10px 16px;color:#5f6368}
.gm-search svg{width:18px;height:18px;flex:none}
.gm-ava{width:32px;height:32px;border-radius:50%;background:#7b1fa2;color:#fff;display:grid;place-items:center;font-weight:600;margin-left:auto;flex:none}
.gm-tabs{display:flex;border-bottom:1px solid #f1f3f4}
.gm-tab{display:flex;align-items:center;gap:10px;padding:13px 18px;font-size:14px;color:#5f6368;font-weight:500;border-bottom:3px solid transparent}
.gm-tab.on{color:#0b57d0;border-bottom-color:#0b57d0}.gm-tab svg{width:18px;height:18px}
.gm-row{display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:14px;padding:11px 18px;border-bottom:1px solid #f5f5f5}
.gm-av{width:36px;height:36px;border-radius:50%;color:#fff;display:grid;place-items:center;font-weight:600;font-size:15px;overflow:hidden}
.gm-av img{width:100%;height:100%;object-fit:cover}
.gm-txt{min-width:0;display:flex;flex-direction:column;gap:2px}
.gm-sender{font-size:14px;color:#5f6368}
.gm-line{font-size:13.5px;color:#5f6368;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.gm-line b{color:#202124}
.gm-time{font-size:12.5px;color:#5f6368;white-space:nowrap}
.gm-blur{filter:blur(3.5px);opacity:.8;user-select:none}
.gm-hot{background:#f2f6fc;box-shadow:inset 4px 0 0 #0b57d0}
.gm-hot .gm-sender,.gm-hot .gm-line b,.gm-hot .gm-time{color:#1f1f1f;font-weight:700}

/* WhatsApp */
.wa-btn{display:inline-flex;align-items:center;gap:12px;background:#25D366;color:#fff;font-weight:700;font-size:17px;border-radius:10px;padding:17px 30px;min-height:56px;
  box-shadow:0 16px 36px -12px rgba(37,211,102,.55);transition:transform .2s var(--ease),filter .2s}
.wa-btn:hover{transform:translateY(-2px);filter:brightness(1.04)}
.wa-btn svg{width:26px;height:26px}
.wa-note{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:22px;font-size:14.5px;color:var(--text-2)}
.wa-note img{width:44px;height:auto;border-radius:4px;transform:rotate(-4deg);box-shadow:0 8px 18px rgba(0,0,0,.6)}

@media(max-width:620px){.step{padding:30px 18px 32px}.gm-logo span,.gm-top svg.gm-burger{display:none}.gm-row{gap:10px;padding:10px 12px}}
